body.content:
[
  {
    "name": "theme_info",
    "theme_name": "Velantra Quiet Luxury",
    "theme_version": "1.0.0",
    "theme_author": "Velantra",
    "theme_documentation_url": "https://help.shopify.com/en/manual/online-store/themes",
    "theme_support_url": "https://velantrafashion.com/pages/contact"
  },
  {
    "name": "Colors",
    "settings": [
      {
        "type": "color",
        "id": "color_background",
        "label": "Page background",
        "default": "#fdfdfd"
      },
      {
        "type": "color",
        "id": "color_text",
        "label": "Text",
        "default": "#2a2a2a"
      },
      {
        "type": "color",
        "id": "color_line",
        "label": "Dividers",
        "default": "#d1d1cd"
      },
      {
        "type": "color",
        "id": "color_muted",
        "label": "Secondary text",
        "default": "#686861"
      },
      {
        "type": "color",
        "id": "studio_background",
        "label": "Studio background",
        "default": "#ffffff"
      }
    ]
  },
  {
    "name": "Typography",
    "settings": [
      {
        "type": "checkbox",
        "id": "custom_fonts",
        "label": "Use custom fonts",
        "default": false
      },
      {
        "type": "font_picker",
        "id": "body_font",
        "label": "Body font",
        "default": "montserrat_n4"
      },
      {
        "type": "font_picker",
        "id": "heading_font",
        "label": "Heading font",
        "default": "serif"
      }
    ]
  },
  {
    "name": "Layout and brand",
    "settings": [
      {
        "type": "checkbox",
        "id": "transparent_header",
        "label": "Transparent homepage header",
        "default": true
      },
      {
        "type": "range",
        "id": "page_width",
        "label": "Page width",
        "min": 1000,
        "max": 2000,
        "step": 50,
        "unit": "px",
        "default": 1600
      },
      {
        "type": "range",
        "id": "section_spacing",
        "label": "Section spacing",
        "min": 40,
        "max": 160,
        "step": 8,
        "unit": "px",
        "default": 96
      },
      {
        "type": "image_picker",
        "id": "favicon",
        "label": "Favicon"
      },
      {
        "type": "url",
        "id": "instagram",
        "label": "Instagram URL"
      },
      {
        "type": "url",
        "id": "facebook",
        "label": "Facebook URL"
      }
    ]
  },
  {
    "name": "Studio catalog",
    "settings": [
      {
        "type": "checkbox",
        "id": "use_studio_catalog",
        "label": "Use included white studio product images",
        "default": true
      },
      {
        "type": "paragraph",
        "content": "White studio images are scoped to this theme. Newly uploaded product media uses its own image automatically."
      }
    ]
  },
  {
    "name": "Product prices",
    "settings": [
      {
        "type": "checkbox",
        "id": "show_compare_at_prices",
        "label": "Show compare-at prices",
        "default": true,
        "info": "Displays Shopify compare-at prices only when higher than the current variant price."
      }
    ]
  },
  {
    "name": "Preorders",
    "settings": [
      {
        "type": "checkbox",
        "id": "vivienne_preorder",
        "label": "Vivienne preorder enabled",
        "default": true
      },
      {
        "type": "textarea",
        "id": "vivienne_preorder_message",
        "label": "Vivienne preorder message",
        "default": "Pre-order. Every colorway is made to order. Expected to ship October."
      },
      {
        "type": "checkbox",
        "id": "colette_preorder",
        "label": "Colette preorder enabled",
        "default": true
      },
      {
        "type": "textarea",
        "id": "colette_preorder_message",
        "label": "Colette preorder message",
        "default": "Pre-order. Expected to ship early October."
      },
      {
        "type": "checkbox",
        "id": "weekender_black_preorder",
        "label": "Eleanor Black preorder enabled",
        "default": true
      },
      {
        "type": "textarea",
        "id": "weekender_black_preorder_message",
        "label": "Eleanor Black preorder message",
        "default": "Pre-order. Black is all leather with no canvas. Expected to ship mid September 2026."
      }
    ]
  }
]

{% if section.settings.text != blank %}<div class="announcement" style="background:{{ section.settings.background }};color:{{ section.settings.color }}">{% if section.settings.link != blank %}<a href="{{ section.settings.link }}">{% endif %}{{ section.settings.text | escape }}{% if section.settings.link != blank %}</a>{% endif %}</div>{% endif %}
{% schema %}
{
  "name": "Announcement",
  "settings": [
    {
      "type": "text",
      "id": "text",
      "label": "Announcement"
    },
    {
      "type": "url",
      "id": "link",
      "label": "Link"
    },
    {
      "type": "color",
      "id": "background",
      "label": "Background",
      "default": "#2a2a2a"
    },
    {
      "type": "color",
      "id": "color",
      "label": "Text",
      "default": "#ffffff"
    }
  ],
  "presets": [
    {
      "name": "Announcement"
    }
  ]
}
{% endschema %}

{%- capture review_content -%}
  {% for block in section.blocks %}
    {% render block %}
  {% endfor %}
{%- endcapture -%}
{%- liquid
  assign review_content = review_content | strip
  assign review_label = section.settings.heading | default: product.title
-%}
{% if review_content != blank or section.settings.show_empty_state %}
  <section class="client-perspectives" aria-label="{{ review_label | escape }}">
    {% if section.settings.heading != blank %}
      <header class="client-perspectives__header">
        <h2>{{ section.settings.heading | escape }}</h2>
      </header>
    {% endif %}
    <div class="client-perspectives__body">
      {% if review_content != blank %}
        {{ review_content }}
      {% else %}
        <p class="client-perspectives__empty">{{ section.settings.empty_text | escape }}</p>
      {% endif %}
    </div>
  </section>
{% endif %}

{% stylesheet %}
  .client-perspectives {
    padding-block: 40px 64px;
    background: var(--color-bg);
    color: var(--color-text);
    font-family: var(--font-sans);
  }

  .client-perspectives__header {
    margin: 0 12px 40px;
    padding-bottom: 24px;
    border-bottom: 1px solid var(--color-line);
    text-align: center;
  }

  .client-perspectives__header h2 {
    margin: 0;
    font-family: var(--font-serif);
    font-size: 22px;
    font-weight: 400;
    line-height: 1.25;
    overflow-wrap: anywhere;
  }

  .client-perspectives__body {
    width: 100%;
    max-width: 1200px;
    min-width: 0;
    margin-inline: auto;
    padding-inline: 20px;
  }

  .client-perspectives__body > * {
    max-width: 100%;
  }

  .client-perspectives__empty {
    max-width: 42rem;
    margin: 0 auto;
    padding-block: 40px;
    font-size: 13px;
    line-height: 1.6;
    text-align: center;
    overflow-wrap: anywhere;
  }

  @media (min-width: 1024px) {
    .client-perspectives {
      padding-block: 80px 112px;
    }

    .client-perspectives__header {
      text-align: left;
    }

    .client-perspectives__header h2 {
      font-size: 32px;
    }

    .client-perspectives__body {
      padding-inline: 32px;
    }
  }
{% endstylesheet %}

{% schema %}
{
  "name": "Client perspectives",
  "limit": 1,
  "max_blocks": 4,
  "enabled_on": { "templates": ["product"] },
  "settings": [
    { "type": "text", "id": "heading", "label": "Heading", "default": "Client Perspectives" },
    { "type": "paragraph", "content": "Add your reviews app block to display this product's customer reviews. The app supplies review text, ratings, photos and verification status." },
    { "type": "checkbox", "id": "show_empty_state", "label": "Show section when no reviews app is configured", "default": true },
    { "type": "textarea", "id": "empty_text", "label": "Empty state text", "default": "Customer reviews are not available here yet." }
  ],
  "blocks": [{ "type": "@app" }],
  "presets": [{ "name": "Client perspectives" }]
}
{% endschema %}

{% liquid
  assign cover = section.settings.poster | default: section.settings.video.preview_image
  if cover != blank
    assign cover_url = cover | image_url: width: 2000
  else
    assign cover_url = 'vivienne-detail-film-poster.jpg' | asset_url
  endif
%}
<velantra-detail-film class="detail-film" aria-label="{{ section.settings.description | escape }}" style="--film-position:50% {{ section.settings.vertical_position }}%">
  {% if section.settings.video != blank %}
    {{ section.settings.video | video_tag: autoplay: false, loop: true, muted: true, controls: true, preload: 'none', image_size: '2000x', poster: cover_url, class: 'detail-film-video' }}
  {% else %}
    <img class="detail-film-poster" src="{{ cover_url }}" width="1920" height="1080" loading="lazy" alt="{{ section.settings.description | escape }}">
  {% endif %}
  <button class="detail-film-toggle" type="button" aria-label="{{ 'general.play_film' | t }}" data-play-label="{{ 'general.play_film' | t }}" data-pause-label="{{ 'general.pause_film' | t }}" hidden>
    <svg class="detail-film-play" width="14" height="14" viewBox="0 0 16 16" aria-hidden="true"><path d="M4 2.5 13 8 4 13.5Z" fill="currentColor"/></svg>
    <svg class="detail-film-pause" width="14" height="14" viewBox="0 0 16 16" aria-hidden="true" hidden><path d="M4 2h3v12H4zm5 0h3v12H9z" fill="currentColor"/></svg>
  </button>
</velantra-detail-film>
{% stylesheet %}
  .detail-film{display:block;position:relative;width:100%;aspect-ratio:1434/726;background:#000;overflow:hidden}
  .detail-film .detail-film-video,.detail-film .detail-film-poster{width:100%;height:100%;object-fit:cover;object-position:var(--film-position);opacity:.85}
  .template-product .detail-film{aspect-ratio:1434/750}
  .detail-film-toggle{position:absolute;bottom:20px;right:20px;display:grid;place-items:center;width:44px;height:44px;border:1px solid #ffffff9c;border-radius:50%;background:#0003;color:#fff;backdrop-filter:blur(8px)}
  .detail-film-toggle:hover{background:#0006}
  @media(max-width:1023px){.detail-film{aspect-ratio:390/340}.template-product .detail-film{aspect-ratio:390/420}.detail-film-toggle{bottom:12px;right:12px}}
{% endstylesheet %}
{% javascript %}
  if (!customElements.get('velantra-detail-film')) {
    customElements.define('velantra-detail-film', class extends HTMLElement {
      connectedCallback() {
        this.video = this.querySelector('video');
        this.button = this.querySelector('.detail-film-toggle');
        if (!this.video || !this.button) return;
        this.events = new AbortController();
        const options = { signal: this.events.signal };
        this.motion = window.matchMedia('(prefers-reduced-motion: reduce)');
        this.visible = false;
        this.userPaused = false;
        this.video.muted = true;
        this.video.playsInline = true;
        this.video.controls = false;
        this.button.hidden = false;
        const sync = () => {
          const paused = this.video.paused;
          this.button.setAttribute('aria-label', paused ? this.button.dataset.playLabel : this.button.dataset.pauseLabel);
          this.button.querySelector('.detail-film-play').hidden = !paused;
          this.button.querySelector('.detail-film-pause').hidden = paused;
        };
        const play = () => this.video.play().catch(sync);
        this.button.addEventListener('click', () => {
          if (this.video.paused) { this.userPaused = false; play(); }
          else { this.userPaused = true; this.video.pause(); }
        }, options);
        this.video.addEventListener('play', sync, options);
        this.video.addEventListener('pause', sync, options);
        this.video.addEventListener('error', () => { this.video.controls = true; this.button.hidden = true; }, options);
        this.motion.addEventListener('change', () => {
          if (this.motion.matches) this.video.pause();
          else if (this.visible && !this.userPaused) play();
        }, options);
        document.addEventListener('visibilitychange', () => {
          if (document.hidden) this.video.pause();
          else if (this.visible && !this.motion.matches && !this.userPaused) play();
        }, options);
        this.observer = new IntersectionObserver(entries => {
          this.visible = entries[0].isIntersecting && entries[0].intersectionRatio >= 0.15;
          if (this.visible && !this.motion.matches && !this.userPaused && !document.hidden) play();
          else this.video.pause();
        }, { threshold: 0.15 });
        this.observer.observe(this);
        sync();
      }
      disconnectedCallback() {
        this.events?.abort();
        this.observer?.disconnect();
        this.video?.pause();
      }
    });
  }
{% endjavascript %}
{% schema %}
{
  "name": "Detail film",
  "settings": [
    { "type": "video", "id": "video", "label": "Video" },
    { "type": "image_picker", "id": "poster", "label": "Cover image" },
    { "type": "range", "id": "vertical_position", "label": "Vertical focal point", "min": 0, "max": 100, "step": 5, "unit": "%", "default": 65 },
    { "type": "text", "id": "description", "label": "Description", "default": "Vivienne: leather, braided edge, handles and gold hardware in close-up" }
  ],
  "presets": [{ "name": "Detail film" }]
}
{% endschema %}

{%- liquid
  assign horizontal_padding = section.settings.side_padding | times: 2
  assign column_gaps = section.settings.columns | minus: 1 | times: section.settings.gap
  assign collection_url = section.settings.collection.url | default: routes.all_products_collection_url
  assign section_label = section.settings.heading | default: section.settings.eyebrow
  if section_label == blank
    assign section_label = 'general.collection' | t
  endif
-%}
{%- capture image_sizes -%}
  (min-width: 768px) calc((100vw - {{ horizontal_padding }}px - {{ column_gaps }}px) / {{ section.settings.columns }}), {% if section.settings.mobile_layout == 'scroll' %}82vw{% else %}calc(100vw - {{ horizontal_padding }}px){% endif %}
{%- endcapture -%}
<section
  class="featured-model-collection featured-model-collection--{{ section.settings.mobile_layout }}"
  aria-label="{{ section_label | escape }}"
  style="--model-columns: {{ section.settings.columns }}; --model-ratio: {{ section.settings.ratio }}; --model-gap: {{ section.settings.gap }}px; --model-side-padding: {{ section.settings.side_padding }}px; --model-vertical-padding: {{ section.settings.vertical_padding }}px;"
>
  {% if section.settings.heading != blank or section.settings.eyebrow != blank or section.settings.show_collection_link %}
    <div class="featured-model-collection__heading">
      <div>
        {% if section.settings.eyebrow != blank %}
          <p class="eyebrow">{{ section.settings.eyebrow | escape }}</p>
        {% endif %}
        {% if section.settings.heading != blank %}
          <h2>{{ section.settings.heading | escape }}</h2>
        {% endif %}
      </div>
      {% if section.settings.show_collection_link %}
        <a class="text-link" href="{{ collection_url }}">{{ 'general.view_collection' | t }}</a>
      {% endif %}
    </div>
  {% endif %}
  <ul class="featured-model-collection__grid" role="list">
    {% for block in section.blocks %}
      {%- liquid
        assign card_product = block.settings.product
        assign card_variant = blank
        assign requested_variant_id = block.settings.variant_id | strip | plus: 0
        if requested_variant_id > 0 and card_product != blank
          for candidate_variant in card_product.variants
            if candidate_variant.id == requested_variant_id
              assign card_variant = candidate_variant
              break
            endif
          endfor
        endif
        assign card_url = card_product.url
        if card_variant != blank
          assign card_url = card_url | append: '?variant=' | append: card_variant.id
        endif
        assign card_title = block.settings.title | default: card_product.title
        if card_title == blank
          assign card_title = 'general.collection' | t
        endif
        assign card_image = card_variant.featured_image | default: card_product.featured_image
        assign image_alt = block.settings.alt_text | default: block.settings.image.alt | default: card_product.title | default: card_title
        assign image_position = block.settings.image_position
        if image_position == 'focal'
          assign image_position = block.settings.image.presentation.focal_point | default: card_image.presentation.focal_point | default: '50% 50%'
        endif
        assign image_loading = 'lazy'
        if section.index == 1 and forloop.index <= section.settings.columns
          assign image_loading = 'eager'
        endif
        capture studio_image
          render 'studio-image-url', image: card_image, product: card_product
        endcapture
        assign studio_image = studio_image | strip
      -%}
      {% if card_product != blank or request.design_mode %}
        <li
          class="featured-model-collection__item"
          style="--model-image-fit: {{ block.settings.image_fit }}; --model-image-position: {{ image_position }};"
          {{ block.shopify_attributes }}
        >
          {% if card_product != blank %}
            <a class="featured-model-collection__media" href="{{ card_url }}" aria-label="{{ card_title | escape }}">
          {% else %}
            <div class="featured-model-collection__media">
          {% endif %}
            {% if block.settings.image != blank %}
              {{ block.settings.image | image_url: width: 2000 | image_tag: widths: '400, 600, 900, 1200, 1600, 2000', sizes: image_sizes, loading: image_loading, alt: image_alt }}
            {% elsif block.settings.image_url != blank %}
              <img src="{{ block.settings.image_url | escape }}" width="1200" height="1500" loading="{{ image_loading }}" alt="{{ image_alt | escape }}">
            {% elsif studio_image != blank %}
              <img src="{{ studio_image | escape }}" width="1200" height="1500" loading="{{ image_loading }}" alt="{{ image_alt | escape }}">
            {% elsif card_image != blank %}
              {{ card_image | image_url: width: 2000 | image_tag: widths: '400, 600, 900, 1200, 1600, 2000', sizes: image_sizes, loading: image_loading, alt: image_alt }}
            {% else %}
              {{ 'product-apparel-1' | placeholder_svg_tag: 'featured-model-collection__placeholder' }}
            {% endif %}
          {% if card_product != blank %}
            </a>
          {% else %}
            </div>
          {% endif %}
          <div class="featured-model-collection__details">
            <h3>
              {% if card_product != blank %}
                <a href="{{ card_url }}">{{ card_title | escape }}</a>
              {% else %}
                {{ card_title | escape }}
              {% endif %}
            </h3>
            {% if section.settings.show_prices and card_product != blank %}
              <div class="featured-model-collection__price">
                {% render 'product-price', product: card_product, variant: card_variant %}
              </div>
            {% endif %}
          </div>
        </li>
      {% endif %}
    {% endfor %}
  </ul>
</section>

{% stylesheet %}
  .featured-model-collection {
    padding-block: var(--model-vertical-padding);
  }

  .featured-model-collection__heading {
    display: flex;
    align-items: end;
    justify-content: space-between;
    gap: 24px;
    margin: 0 max(20px, var(--model-side-padding)) 36px;
  }

  .featured-model-collection__heading .eyebrow {
    margin-bottom: 14px;
  }

  .featured-model-collection__heading .text-link {
    flex-shrink: 0;
  }

  .featured-model-collection__grid {
    display: grid;
    grid-template-columns: repeat(var(--model-columns), minmax(0, 1fr));
    align-items: start;
    gap: 32px var(--model-gap);
    margin: 0;
    padding: 0 var(--model-side-padding);
    list-style: none;
  }

  .featured-model-collection__item {
    position: relative;
    min-width: 0;
  }

  .featured-model-collection__media {
    position: relative;
    display: block;
    width: 100%;
    aspect-ratio: var(--model-ratio);
    overflow: hidden;
    background: var(--studio-bg, #fff);
  }

  .featured-model-collection__media img,
  .featured-model-collection__placeholder {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: var(--model-image-fit);
    object-position: var(--model-image-position) !important;
  }

  .featured-model-collection__media:focus-visible {
    outline-offset: -4px;
  }

  .featured-model-collection__details {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 8px 20px;
    padding: 18px 12px 6px;
  }

  .featured-model-collection__details h3 {
    font-family: var(--font-sans);
    font-size: 11px;
    font-weight: 500;
    line-height: 1.5;
    letter-spacing: 1px;
    text-transform: uppercase;
    overflow-wrap: anywhere;
  }

  .featured-model-collection__details a:hover {
    text-decoration: underline;
    text-underline-offset: 4px;
  }

  .featured-model-collection__price {
    min-width: 0;
    max-width: 100%;
    font-size: 11px;
    line-height: 1.5;
  }

  @media (max-width: 767px) {
    .featured-model-collection__heading {
      align-items: start;
      flex-wrap: wrap;
      gap: 20px;
      margin-bottom: 28px;
    }

    .featured-model-collection__heading h2 {
      font-size: 26px;
    }

    .featured-model-collection--scroll .featured-model-collection__grid {
      grid-template-columns: none;
      grid-auto-flow: column;
      grid-auto-columns: 82vw;
      overflow-x: auto;
      overscroll-behavior-x: contain;
      scroll-snap-type: x mandatory;
      scroll-padding-inline: var(--model-side-padding);
      padding-bottom: 12px;
    }

    .featured-model-collection--scroll .featured-model-collection__item {
      scroll-snap-align: start;
    }

    .featured-model-collection--stack .featured-model-collection__grid {
      grid-template-columns: minmax(0, 1fr);
    }

    .featured-model-collection__details {
      padding-inline: 12px;
    }
  }
{% endstylesheet %}

{% schema %}
{
  "name": "Featured model collection",
  "max_blocks": 12,
  "disabled_on": {
    "groups": ["header", "footer"]
  },
  "settings": [
    { "type": "text", "id": "heading", "label": "Heading", "default": "FEATURED COLLECTION" },
    { "type": "text", "id": "eyebrow", "label": "Eyebrow" },
    { "type": "collection", "id": "collection", "label": "Collection link destination" },
    { "type": "checkbox", "id": "show_collection_link", "label": "Show collection link", "default": true },
    { "type": "checkbox", "id": "show_prices", "label": "Show prices", "default": true },
    {
      "type": "select",
      "id": "ratio",
      "label": "Image ratio",
      "options": [
        { "value": "4/5", "label": "Portrait (4:5)" },
        { "value": "3/4", "label": "Portrait (3:4)" },
        { "value": "1/1", "label": "Square (1:1)" }
      ],
      "default": "4/5"
    },
    { "type": "range", "id": "columns", "label": "Desktop columns", "min": 1, "max": 4, "step": 1, "default": 3 },
    { "type": "range", "id": "gap", "label": "Space between images", "min": 0, "max": 40, "step": 2, "unit": "px", "default": 12 },
    {
      "type": "select",
      "id": "mobile_layout",
      "label": "Mobile layout",
      "options": [
        { "value": "scroll", "label": "Horizontal scroll" },
        { "value": "stack", "label": "Stacked" }
      ],
      "default": "scroll"
    },
    { "type": "range", "id": "side_padding", "label": "Side spacing", "min": 0, "max": 48, "step": 2, "unit": "px", "default": 0 },
    { "type": "range", "id": "vertical_padding", "label": "Top and bottom spacing", "min": 0, "max": 120, "step": 4, "unit": "px", "default": 64 }
  ],
  "blocks": [
    {
      "type": "product",
      "name": "Model product",
      "settings": [
